//#region plugin/src/index.js
const inject = [
	"react",
	"agents",
	"settingsCards"
];
function apply(ctx) {
	const React = ctx.react;
	const uiKit = ui(React);
	const { Btn } = createBuzzPrimitives(React);
	const client = createClient();
	ctx.effect(() => () => client.close());
	const relay = ctx.reflect?.get?.("relay");
	const { invalidateCatalog, hostedModels, hostedSessions } = createComposer({
		client,
		ctx
	});
	const { ActivityTab } = createActivity({
		React,
		ctx,
		uiKit,
		relay
	});
	const { OrchestratorSettings } = createOrchestrator({
		React,
		client,
		uiKit
	});
	const { InviteOverlay, InviteMessageCard, matchesInviteMessage } = createInviteFeature({
		React,
		client,
		relay,
		uiKit,
		Btn
	});
	createType({
		React,
		client,
		ctx,
		uiKit,
		invalidateCatalog,
		ActivityTab,
		OrchestratorSettings,
		hostedModels,
		hostedSessions
	});
	ctx.settingsCards.register({
		id: "server",
		title: "Remote Agents",
		group: "Plugins",
		component: createServerCard({
			React,
			client,
			uiKit,
			Btn,
			relay
		})
	});
	ctx.inject?.(["conversation"], (scope) => {
		scope.conversation?.registerMessage?.({
			id: "guest-invite",
			title: "Remote Agents invite",
			matches: matchesInviteMessage,
			component: InviteMessageCard
		});
	});
	ctx.inject?.(["pages"], (scope) => {
		try {
			scope.pages?.registerOverlay?.({
				id: "guest-invite",
				component: InviteOverlay
			});
		} catch {}
	});
}

